/**
 * Karnataka state outline for the Geography dock item: the outer boundary only (no district lines),
 * filled with the flag colours, yellow above and red below, with an ink outline.
 * Generated from KarnatakaGeometry (district edges that appear once). Coordinates are 0..1000 on the long side.
 */
@Composable
fun KarnatakaStateGlyph(modifier: Modifier = Modifier, glyphSize: androidx.compose.ui.unit.Dp = Space.X20) {
    Canvas(modifier = modifier.size(glyphSize)) {
        val state = Path()
        val scale = this.size.minDimension / 1000f
        val ox = (this.size.width - 633f * scale) / 2f
        val oy = (this.size.height - 1000f * scale) / 2f
        KARNATAKA_STATE_RINGS.forEach { ring ->
            ring.forEachIndexed { i, p ->
                val o = Offset(ox + p[0] * scale, oy + p[1] * scale)
                if (i == 0) state.moveTo(o.x, o.y) else state.lineTo(o.x, o.y)
            }
            state.close()
        }
        // Upper half yellow, lower half red: the flag colours
        clipHalf(top = true) { drawPath(state, BenneButterYellow) }
        clipHalf(top = false) { drawPath(state, BennePopRed) }
        drawPath(state, PopPosterInk, style = Stroke(width = Dim.S1_2.toPx()))
    }
}

private inline fun androidx.compose.ui.graphics.drawscope.DrawScope.clipHalf(top: Boolean, block: androidx.compose.ui.graphics.drawscope.DrawScope.() -> Unit) {
    val half = size.height / 2f
    val rect = androidx.compose.ui.geometry.Rect(0f, if (top) 0f else half, size.width, if (top) half else size.height)
    clipRect(rect.left, rect.top, rect.right, rect.bottom) { block() }
}

